package io.gluonify.source.documents;

import io.gluonify.plasma.crystallon.client.RenderOptions;
import io.gluonify.source.documents.generated.GluonifyInvoicePayload;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;

/**
 * From the application's own {@link InvoiceRequest} to the payload of the Crystallon template (the records generated by the "Code" tab, package {@code generated}).
 * This is the only place that knows the shape of the template: when Crystallon's template changes and the code is generated again, only this class may need an update
 * (the compiler tells you where).
 */
public final class InvoiceMapping {
    /** Swiss standard VAT rate, in percent: used when the request gives none. */
    static final BigDecimal DEFAULT_VAT_RATE = new BigDecimal("8.1");

    /**
     * The issuer printed in the header of the invoice. An example: your own company's details, normally read from your configuration or from your data (Gdown),
     * not written in the code.
     */
    static final GluonifyInvoicePayload.Sender ISSUER = new GluonifyInvoicePayload.Sender("Gluonify Source Example Ltd", "Bahnhofstrasse", "12", "8001", "Zurich", "CH",
            "billing@source.example", null, null, null, null, null);

    private InvoiceMapping() {}

    /** @param today the date used when the request has none (a parameter, so that tests do not depend on the clock) */
    public static GluonifyInvoicePayload payload(InvoiceRequest in, LocalDate today) {
        InvoiceRequest.Customer c = in.customer();
        GluonifyInvoicePayload.Recipient recipient = new GluonifyInvoicePayload.Recipient(c.name(), null, c.street(), c.houseNumber(), c.postalCode(), c.city(), c.country(), null);
        GluonifyInvoicePayload.Invoice invoice = new GluonifyInvoicePayload.Invoice(in.number(), in.date() == null ? today : in.date(), in.dueDate(), in.subject(), null);
        List<GluonifyInvoicePayload.Item> items = in.lines().stream()
                .map(l -> new GluonifyInvoicePayload.Item(l.description(), l.quantity(), l.unit() == null || l.unit().isBlank() ? "pce" : l.unit(), l.unitPrice(),
                        l.quantity().multiply(l.unitPrice()).setScale(2, RoundingMode.HALF_UP)))
                .toList();
        // no payment: the template prints a QR-bill only when payment.iban is present
        return new GluonifyInvoicePayload(ISSUER, recipient, invoice, items, in.vatRate() == null ? DEFAULT_VAT_RATE : in.vatRate(), null);
    }

    /** Rendering options: only the language is asked for; currency, country and time zone are the template's (CHF, CH, Europe/Zurich), PDF/A-1B is the SDK default. */
    public static RenderOptions options(InvoiceRequest in) {
        return in.lang() == null ? RenderOptions.DEFAULT : RenderOptions.builder().lang(in.lang()).build();
    }

    /** A file name made of safe characters only (the invoice number comes from the caller): {@code invoice-2026-0042.pdf}. */
    public static String fileName(InvoiceRequest in) {
        String safe = in.number().replaceAll("[^A-Za-z0-9._-]", "_");
        return "invoice-" + (safe.length() > 40 ? safe.substring(0, 40) : safe) + ".pdf";
    }
}
